const row = items[0]?.json ?? {};

const safe = (value, fallback = '') => String(value ?? fallback).trim();
const asInt = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

const leadId = row.lead_id;
const clickupTaskId = safe(row.clickup_task_id);
const sellerClickUpUserId = asInt(row.clickup_user_id);

if (!leadId) {
  throw new Error('CRM - Seller Notification Dispatch requiere lead_id');
}

if (!clickupTaskId) {
  throw new Error('El lead aun no tiene tarea ClickUp creada; no se notifica al vendedor');
}

if (!sellerClickUpUserId) {
  throw new Error('El vendedor asignado no tiene clickup_user_id configurado');
}

if (!safe($env.CLICKUP_API_TOKEN)) {
  throw new Error('CLICKUP_API_TOKEN no esta configurado para notificaciones internas');
}

const sellerName = safe(row.seller_name, 'Equipo Comercial');
const leadName = safe(row.whatsapp_name, 'Lead sin nombre');
const service = safe(row.service, 'Sin servicio');
const city = safe(row.city, 'Sin ciudad');
const requirement = safe(row.requirement, 'Sin requerimiento informado');
const customerPhone = safe(row.phone_number, 'No informado');
const clickupUrl = safe(row.clickup_task_url);

const notificationText = [
  'Nuevo lead listo para gestionar.',
  '',
  'Vendedor: ' + sellerName,
  'Nombre: ' + leadName,
  'Telefono: ' + customerPhone,
  'Servicio: ' + service,
  'Ciudad: ' + city,
  'Requerimiento: ' + requirement,
  clickupUrl ? 'ClickUp: ' + clickupUrl : null,
].filter(Boolean).join('\n');

return [
  {
    json: {
      lead_id: leadId,
      seller_id: row.seller_id,
      seller_name: sellerName,
      seller_clickup_user_id: sellerClickUpUserId,
      notification_channel: 'clickup',
      notification_operation_key: row.operation_key,
      notification_operation_status: row.notification_operation_status,
      notification_reconciliation_required: Boolean(row.notification_reconciliation_required),
      notification_reconciliation_reason: row.notification_reconciliation_reason || null,
      should_dispatch_notification: Boolean(row.should_dispatch_notification),
      notification_url: 'https://api.clickup.com/api/v2/task/' + encodeURIComponent(clickupTaskId) + '/comment',
      notification_payload: {
        comment_text: notificationText,
        assignee: sellerClickUpUserId,
        notify_all: false,
      },
    },
  },
];

const normalizeBody = (value) => {
  if (typeof value === 'string') { try { return JSON.parse(value); } catch (_error) { return { raw: value }; } }
  return value || {};
};
const result = (statusCode, body, outcome, extra={}) => ({
  statusCode, body: normalizeBody(body), headers: {}, retry_attempts: extra.attempts || 0,
  retry_exhausted: false, retry_last_error: extra.error || null,
  operation_outcome: outcome, reconciliation_required: outcome === 'unknown',
  retry_safe: Boolean(extra.retry_safe), idempotency_in_progress: outcome === 'in_progress',
});
const row = items[0]?.json ?? {};
if (!row.should_dispatch_notification) {
  const status = String(row.notification_operation_status || 'in_progress');
  if (status === 'succeeded') return [{ json: result(200, {}, 'succeeded') }];
  if (status === 'unknown' || row.notification_reconciliation_required) return [{ json: result(0, { message: row.notification_reconciliation_reason || 'Manual reconciliation required' }, 'unknown') }];
  if (status === 'failed') return [{ json: result(0, { message: 'Notification failed and is not safe to retry automatically' }, 'failed') }];
  return [{ json: result(202, {}, 'in_progress') }];
}
const url = String(row.notification_url || '').trim();
const body = row.notification_payload;
if (!url) throw new Error('Dispatch Notification requiere notification_url');
if (!body) throw new Error('Dispatch Notification requiere notification_payload');
try {
  const response = await helpers.httpRequest({
    method:'POST', url,
    headers:{ Authorization:$env.CLICKUP_API_TOKEN, 'Content-Type':'application/json' },
    body, json:true, returnFullResponse:true, ignoreHttpStatusErrors:true,
  });
  const statusCode=Number(response.statusCode||0);
  if (statusCode>=200 && statusCode<300) return [{ json: result(statusCode,response.body,'succeeded',{attempts:1}) }];
  if (statusCode===408 || statusCode>=500 || statusCode===0) return [{ json: result(statusCode,response.body,'unknown',{attempts:1}) }];
  return [{ json: result(statusCode,response.body,'failed',{attempts:1,retry_safe:[425,429].includes(statusCode)}) }];
} catch(error) {
  return [{ json: result(0,{message:error.message},'unknown',{attempts:1,error:error.message}) }];
}

const row = items[0]?.json ?? {};

const statusCode = Number(row.statusCode_2 || row.statusCode || 0);
const responseBody = row.body_2 || row.body || {};
const retryAttempts = Number(row.retry_attempts_2 || row.retry_attempts || 1);
const retryExhausted = Boolean(row.retry_exhausted_2 || row.retry_exhausted || false);
const retryLastError = row.retry_last_error_2 || row.retry_last_error || null;
const operationOutcome = String(row.operation_outcome_2 || row.operation_outcome || 'failed');
const reconciliationRequired = Boolean(row.reconciliation_required_2 || row.reconciliation_required || operationOutcome === 'unknown');
const retrySafe = Boolean(row.retry_safe_2 || row.retry_safe || false);
const idempotencyInProgress = Boolean(row.idempotency_in_progress_2 || row.idempotency_in_progress || false);
const isSuccess = operationOutcome === 'succeeded' && statusCode >= 200 && statusCode < 300;

return [
  {
    json: {
      lead_id: row.lead_id_1 || row.lead_id,
      event_name: 'seller_notification_dispatch',
      result: isSuccess ? 'success' : operationOutcome === 'unknown' ? 'unknown' : operationOutcome === 'in_progress' ? 'in_progress' : 'error',
      operation_outcome: operationOutcome,
      reconciliation_required: reconciliationRequired,
      retry_safe: retrySafe,
      idempotency_in_progress: idempotencyInProgress,
      notification_operation_key: row.notification_operation_key_1 || row.notification_operation_key || null,
      is_success: isSuccess,
      after_payload_json: JSON.stringify({
        status_code: statusCode,
        response_body: responseBody,
        retry_attempts: retryAttempts,
        retry_exhausted: retryExhausted,
        retry_last_error: retryLastError,
        operation_outcome: operationOutcome,
        reconciliation_required: reconciliationRequired,
        retry_safe: retrySafe,
      }),
      metadata_json: JSON.stringify({
        channel: row.notification_channel_1 || row.notification_channel || 'clickup',
        seller_id: row.seller_id_1 || row.seller_id || null,
        provider: 'clickup',
        retry_attempts: retryAttempts,
        retry_exhausted: retryExhausted,
      }),
    },
  },
];
